            "example": "var builder = WebApplication.CreateBuilder(args);\nbuilder.Services.AddSingleton<TaskStore>();\nvar app = builder.Build();\napp.MapGet(\"/tasks\", (TaskStore store) => store.All());\napp.MapPost(\"/tasks\", (TaskRequest request, TaskStore store) =>\n{\n    if (string.IsNullOrWhiteSpace(request.Title)) return Results.BadRequest(\"Title required\");\n    var item = store.Add(request.Title.Trim());\n    return Results.Created($\"/tasks/{item.Id}\", item);\n});\napp.MapGet(\"/tasks/{id:int}\", (int id, TaskStore store) =>\n    store.All().FirstOrDefault(t => t.Id == id) is { } item\n        ? Results.Ok(item) : Results.NotFound());\napp.Run();\nrecord TaskRequest(string Title);\nrecord TaskItem(int Id, string Title);\nclass TaskStore\n{\n    private readonly List<TaskItem> items = new();\n    private readonly object gate = new();\n    private int nextId = 1;\n    public TaskItem[] All() { lock (gate) return items.ToArray(); }\n    public TaskItem Add(string title)\n    {\n        lock (gate) { var item = new TaskItem(nextId++, title); items.Add(item); return item; }\n    }\n}\n// POST /tasks with {\"title\":\"Read\"} => 201, {\"id\":1,\"title\":\"Read\"}"
